        return grid

    # Find background (most frequent)
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    bg = max(counts, key=counts.get)

    # Collect object positions
    objects = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg:
                objects.append((r, c))

    # Transform background cells
